// Python-repr helpers and a minimal bidirectional mapping.
// Deliberately uses plain objects/arrays only — no Map or Set.

// CPython-style repr for strings.
// Single quotes by default; double quotes when the string contains a
// single quote but no double quote; backslashes and control characters
// escaped as CPython does.
export function pyReprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = '';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return quote + out + quote;
}

// Python repr for the value kinds this script handles (str / int).
export function pyRepr(value) {
  if (typeof value === 'string') {
    return pyReprString(value);
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (value === null || value === undefined) {
    return 'None';
  }
  return String(value);
}

// Minimal bidirectional mapping mirroring the subset of the Python
// `bidict` API the script uses. Keys are strings, values are integers.
// Insertion order is preserved; updating an existing key keeps its
// original position (like a Python dict).
export class Bidict {
  constructor(pairs) {
    // Internal storage:
    //   this._fwd  — plain object, key -> value
    //   this._bwd  — plain object, String(value) -> key
    //   this._keys — array of keys in insertion order
    this._fwd = Object.create(null);
    this._bwd = Object.create(null);
    this._keys = [];
    if (pairs) {
      for (const [key, value] of pairs) {
        this.set(key, value);
      }
    }
  }

  set(key, value) {
    if (Object.prototype.hasOwnProperty.call(this._fwd, key)) {
      // Key exists: drop the stale reverse link, keep position.
      delete this._bwd[String(this._fwd[key])];
    } else {
      this._keys.push(key);
    }
    this._fwd[key] = value;
    this._bwd[String(value)] = key;
  }

  clear() {
    this._fwd = Object.create(null);
    this._bwd = Object.create(null);
    this._keys = [];
  }

  get size() {
    return this._keys.length;
  }

  toString() {
    if (this._keys.length === 0) {
      return 'bidict()';
    }
    const items = this._keys.map(
      (key) => pyReprString(key) + ': ' + pyRepr(this._fwd[key])
    );
    return 'bidict({' + items.join(', ') + '})';
  }
}

