console.log(d.toString()); // 'a' keeps first position, value updated
d.set('b', -3);
console.log(d.toString());
d.clear();
console.log(d.toString());
console.log(pyRepr(\"it's\"));
console.log(pyRepr('say \"hi\"'));
console.log(pyRepr('both \\' and \"'));
console.log(pyRepr('tab\there'));
console.log(pyRepr(-42));
"

