// Minimal argparse mimic for test16.mjs (Node.js ESM, no Map/Set, no deps).

const PROG = 'test16.mjs';
const USAGE = `usage: ${PROG} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3`;

// Declaration order matters: argparse lists missing required flags in this order.
const FLAGS = [
  { name: '--k1', dest: 'k1', metavar: 'K1', type: 'str' },
  { name: '--v1', dest: 'v1', metavar: 'V1', type: 'int' },
  { name: '--k2', dest: 'k2', metavar: 'K2', type: 'str' },
  { name: '--v2', dest: 'v2', metavar: 'V2', type: 'int' },
  { name: '--k3', dest: 'k3', metavar: 'K3', type: 'str' },
  { name: '--v3', dest: 'v3', metavar: 'V3', type: 'int' },
];

function printHelp() {
  const lines = [USAGE, '', 'options:'];
  lines.push('  -h, --help  show this help message and exit');
  for (const f of FLAGS) {
    lines.push(`  ${f.name} ${f.metavar}`);
  }
  console.log(lines.join('\n'));
  process.exit(0);
}

function fail(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function flagByName(name) {
  for (const f of FLAGS) {
    if (f.name === name) return f;
  }
  return null;
}

// Python int(): optional sign followed by digits only (no floats/exponents).
function parseIntStrict(raw) {
  if (!/^[+-]?[0-9]+$/.test(raw)) return null;
  return parseInt(raw, 10);
}

// Python repr of a string for argparse-style error messages: 'abc'
function pyStrRepr(s) {
  return `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

export function parseArgs(argv) {
  const result = {};
  const seen = {};
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      printHelp();
    }

    let name = arg;
    let inlineValue = null;
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(0, eq);
        inlineValue = arg.slice(eq + 1);
      }
    }

    const flag = flagByName(name);
    if (flag === null) {
      unrecognized.push(arg);
      i += 1;
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
      i += 1;
    } else {
      const next = argv[i + 1];
      // A following token that looks like an option string (e.g. --k2, -h)
      // means this flag has no value; a negative number like -5 does not.
      if (next === undefined || /^-[a-zA-Z-]/.test(next)) {
        fail(`argument ${flag.name}: expected one argument`);
      }
      raw = next;
      i += 2;
    }

    if (flag.type === 'int') {
      const parsed = parseIntStrict(raw);
      if (parsed === null) {
        fail(`argument ${flag.name}: invalid int value: ${pyStrRepr(raw)}`);
      }
      result[flag.dest] = parsed;
    } else {
      result[flag.dest] = raw;
    }
    seen[flag.dest] = true;
  }

  if (unrecognized.length > 0) {
    fail(`unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  const missing = [];
  for (const f of FLAGS) {
    if (!seen[f.dest]) missing.push(f.name);
  }
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return {
    k1: result.k1,
    v1: result.v1,
    k2: result.k2,
    v2: result.v2,
    k3: result.k3,
    v3: result.v3,
  };
}

